(3160582, 442633, 5746, '<td valign="top">Fantastic composition. I love the splash of green, which underlines the rythm of the pattern. Without it the picture would''ve been a bit boring.</td>', 'Fantastic composition. I love the splash of green, which underlines the rythm of the pattern. Without it the picture would''ve been a bit boring.', '2006-12-29 18:40:52.000000', NULL, 1),
(3160586, 442020, 5746, '<td valign="top">Great idea. It cryes for full symmetry, however probably than it would''ve been too artificial. Maybe you should resign from the first raw of the barrels and focus on the second one. I like it a lot. 9.</td>', 'Great idea. It cryes for full symmetry, however probably than it would''ve been too artificial. Maybe you should resign from the first raw of the barrels and focus on the second one. I like it a lot. 9.', '2006-12-29 18:42:06.000000', NULL, 1),
(3160588, 442304, 5746, '<td valign="top">Very minimalistic. I wish you cropped the black thick line at the top. Otherwise, I have no idea what it is (blindes?) but I love the graphic feel of it. Looks like a piece of the modern art. 9.</td>', 'Very minimalistic. I wish you cropped the black thick line at the top. Otherwise, I have no idea what it is (blindes?) but I love the graphic feel of it. Looks like a piece of the modern art. 9.', '2006-12-29 18:43:29.000000', NULL, 1),
(3160594, 442737, 5746, '<td valign="top">Original idea. It reminds me of another picture of a fish head in one of the past challenges. Well done. The pattern is clearly visible, although not from the first glance. It seems fish picures have hypnotic power. 9.</td>', 'Original idea. It reminds me of another picture of a fish head in one of the past challenges. Well done. The pattern is clearly visible, although not from the first glance. It seems fish picures have hypnotic power. 9.', '2006-12-29 18:45:16.000000', NULL, 1),
(3160595, 442174, 5746, '<td valign="top">Extraordinary. Minimalistic, very interesting. The red accents are really adding to the compsition, just like the black imperfections in the wall. Lovely textures. Bumping it to 10.</td>', 'Extraordinary. Minimalistic, very interesting. The red accents are really adding to the compsition, just like the black imperfections in the wall. Lovely textures. Bumping it to 10.', '2006-12-29 18:46:34.000000', NULL, 1),
