INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3163872, 441377, 49969, '<td valign="top">That''s a super macro indeed. And a very nice "pattern" shot.</td>', 'That''s a super macro indeed. And a very nice "pattern" shot.', '2006-12-31 03:35:07.000000', NULL, 1),
(3163920, 442280, 53572, '<td valign="top">this could be a very nice image - the texture and colour of the bricks are lovely.  however, your focus is a bit off, and with this kind of image, it really needs to be perfect.</td>', 'this could be a very nice image - the texture and colour of the bricks are lovely.  however, your focus is a bit off, and with this kind of image, it really needs to be perfect.', '2006-12-31 05:57:45.000000', NULL, 1),
(3163923, 441499, 53572, '<td valign="top">this is a good idea, but the exectuion needs a little more.  it''s very grainy, and while with sme images that works very well, it doesn''t here.  the focus isn''t as sharp as it could be.  this really needs a tripod to work well.  the jpeg artifacts around the lights don''t help either.<br/> <br/>it is a good composition, and well spotted.  a pass through noise reduction may help.  also, amke sure sure you''re shooting with your camera on full resolution.<br/> <br/>keep shooting!</td>', 'this is a good idea, but the exectuion needs a little more.  it''s very grainy, and while with sme images that works very well, it doesn''t here.  the focus isn''t as sharp as it could be.  this really needs a tripod to work well.  the jpeg artifacts around the lights don''t help either. it is a good composition, and well spotted.  a pass through noise reduction may help.  also, amke sure sure you''re shooting with your camera on full resolution. keep shooting!', '2006-12-31 06:05:07.000000', NULL, 1),
(3163926, 442550, 53572, '<td valign="top">a very interesting image indeed.  challenging and disturbing.  yes, a pattern could certainly be seen here - the very basic pattern of the circles - jar, lid, head, body, ear.  but, of course, there is the larger, more evanescent pattern of life and its mysteries - how could such a perfectly formed head not finish the job on the rest of the body.<br/> <br/>i can only imagine you''re getting some pretty strongly worded comments on this, as people do seem to overeact a bit sometimes to images that are ''edgy''.  well done for sticking to your guns and submitting this.  i know at least one person has called for it to be withdrawn.<br/> <br/>i''d love to see how you would edit this in advanced editing.  The basic does leave it a little - grey.  i''d love to see some vignetting, gaussian blur on the background, etc etc.  but, of course, then it would be mine, not yours...  (i did a lot of work in the medical museum during my bfa)<br/> <br/>a sad and touching image. i can''t wait to see you take it further.  and to find out who you are!</td>', 'a very interesting image indeed.  challenging and disturbing.  yes, a pattern could certainly be seen here - the very basic pattern of the circles - jar, lid, head, body, ear.  but, of course, there is the larger, more evanescent pattern of life and its mysteries - how could such a perfectly formed head not finish the job on the rest of the body. i can only imagine you''re getting some pretty strongly worded comments on this, as people do seem to overeact a bit sometimes to images that are ''edgy''.  well done for sticking to your guns and submitting this.  i know at least one person has called for it to be withdrawn. i''d love to see how you would edit this in advanced editing.  The basic does leave it a little - grey.  i''d love to see some vignetting, gaussian blur on the background, etc etc.  but, of course, then it would be mine, not yours...  (i did a lot of work in the medical museum during my bfa) a sad and touching image. i can''t wait to see you take it further.  and to find out who you are!', '2006-12-31 06:06:28.000000', NULL, 1),
