(3170748, 442865, 58538, '<td valign="top">You "grabbed my attention". My favorite of the 249 submisions. The ants are a nice touch.</td>', 'You "grabbed my attention". My favorite of the 249 submisions. The ants are a nice touch.', '2007-01-02 12:53:34.000000', NULL, 1),
(3170749, 441825, 40344, '<td valign="top">I like the overall photo but I think it would be stronger with a tighter crop focusing on the fire escape and arched windows.</td>', 'I like the overall photo but I think it would be stronger with a tighter crop focusing on the fire escape and arched windows.', '2007-01-02 12:53:34.000000', NULL, 1),
(3170755, 442218, 58538, '<td valign="top">Nice. I like how this seems to move, I would enjoy this enlarged on my wall.<br/>This is my #2 pick of the entire 249 submisions.<br/>I also apreciate you keeping a realy good depth of field focus</td>', 'Nice. I like how this seems to move, I would enjoy this enlarged on my wall.This is my #2 pick of the entire 249 submisions.I also apreciate you keeping a realy good depth of field focus', '2007-01-02 12:55:19.000000', NULL, 1),
(3170810, 442854, 46996, '<td valign="top">Would have rated it higher with a different backdrop.  Fits challenge well :-)</td>', 'Would have rated it higher with a different backdrop.  Fits challenge well :-)', '2007-01-02 13:20:41.000000', NULL, 1),
