(3180995, 442421, 69448, '<td valign="top">Reminds me of Super Metroid, the super nintendo game. A great game, and a great photo!!</td>', 'Reminds me of Super Metroid, the super nintendo game. A great game, and a great photo!!', '2007-01-04 13:47:21.000000', NULL, 0),
(3181097, 442016, 44490, '<td valign="top">Fascinating shot, the pattern of burners combined with the flames is great, the touch of blue from the pilot flames adds nice color.  Consider lower ISO for less noise.  Very nice.</td>', 'Fascinating shot, the pattern of burners combined with the flames is great, the touch of blue from the pilot flames adds nice color.  Consider lower ISO for less noise.  Very nice.', '2007-01-04 14:17:20.000000', NULL, 0),
(3181113, 442210, 44490, '<td valign="top">Nice shot and good exposure, maybe a title like "Flight Pattern" would help meet the challenge for more voters.</td>', 'Nice shot and good exposure, maybe a title like "Flight Pattern" would help meet the challenge for more voters.', '2007-01-04 14:20:59.000000', NULL, 0),
